addon.ItemAppearance = ItemAppearance

--Flat by-visualID index, built once here rather than duplicated on disk, for callers that look up
--a specific visualID's filename directly instead of iterating by color (SortingFunctions.lua's
--CompareItemColor/FindColorInFile, and the swatch-click ItemAppearance name match).
local ItemAppearanceByID = {}
for _, group in pairs(ItemAppearance) do
	for visualID, file in pairs(group) do
		ItemAppearanceByID[visualID] = file
	end
end
addon.ItemAppearanceByID = ItemAppearanceByID
